html:
{%- set boq = frappe.get_doc("GKD Project BOQ", doc.gkd_project_boq) if doc.gkd_project_boq else None -%}
{%- set site_address = frappe.db.get_value("Project", doc.project, "gkd_site_address") if doc.project else "" -%}
{%- set trade = frappe.db.get_value("Supplier", doc.supplier, "gkd_trade") -%}
<div class="gkd-doc">
	<table class="gkd-head">
		<tr>
			<td class="logo"><img src="/assets/gkd/images/gkd-logo.png" alt="Gauri Khan Designs"></td>
			<td>
				<div class="gkd-brand">GAURI KHAN DESIGN STUDIO</div>
				<div class="gkd-tag">INTERIOR ARCHITECTURE &middot; DESIGN &middot; MUMBAI</div>
			</td>
		</tr>
	</table>

	<h2 class="gkd-title">Scope of Work{% if trade %}: {{ trade | e }}{% endif %}</h2>
	<table class="gkd-meta">
		<tr>
			<td><span>Contractor</span>{{ (doc.supplier_name or doc.supplier) | e }}</td>
			<td><span>Work Order No.</span>{{ doc.name }}</td>
		</tr>
		<tr>
			<td><span>Project</span>{{ (boq.project_name if boq else doc.project or "") | e }}</td>
			<td><span>Order Date</span>{{ doc.get_formatted("transaction_date") }}</td>
		</tr>
		<tr>
			<td><span>Site</span>{{ (site_address or "") | e }}</td>
			<td><span>Complete By</span>{{ doc.get_formatted("schedule_date") }}</td>
		</tr>
		{%- if boq %}
		<tr>
			<td><span>Approved BOQ</span>{{ boq.name }} (Rev. {{ boq.revision_no or 0 }})</td>
			<td><span>Client Approval</span>{{ (boq.approved_by_name or "") | e }}{% if boq.approval_date %}, {{ boq.get_formatted("approval_date") }}{% endif %}</td>
		</tr>
		{%- endif %}
	</table>

	<table class="gkd-boq">
		<thead>
			<tr><th>#</th><th>Room / Area</th><th>Work</th><th>UOM</th><th class="num">Qty</th><th class="num">Rate</th><th class="num">Amount</th></tr>
		</thead>
		<tbody>
			{%- for row in doc.items %}
			<tr>
				<td>{{ row.idx }}</td>
				<td class="wrap">{{ (row.gkd_room_area or "") | e }}</td>
				<td class="wrap">{{ (row.description or row.item_name) | striptags | e }}</td>
				<td>{{ row.uom or "" }}</td>
				<td class="num">{{ row.get_formatted("qty") }}</td>
				<td class="num">{{ row.get_formatted("rate") }}</td>
				<td class="num">{{ row.get_formatted("amount") }}</td>
			</tr>
			{%- endfor %}
		</tbody>
		<tfoot>
			<tr><td colspan="6" class="num">Order Value</td><td class="num">{{ doc.get_formatted("grand_total") }}</td></tr>
		</tfoot>
	</table>

	<ol class="gkd-terms">
		<li>This scope is taken from the BOQ that the client approved in writing. Do only the work listed here.</li>
		<li>Work outside this scope needs a written change order from the Studio before it starts.</li>
		<li>Quantities are measured at site on completion. Payment follows the measured quantity at the rates above.</li>
		<li>Report any site condition that differs from the drawings to the site supervisor before work starts.</li>
	</ol>

	<table class="gkd-sign">
		<tr>
			<td>For Gauri Khan Design Studio<div class="line"></div>Project Manager</td>
			<td>Accepted by the Contractor<div class="line"></div>{{ (doc.supplier_name or doc.supplier) | e }}</td>
		</tr>
	</table>
</div>

<style>
	.gkd-doc, .gkd-contract { font-family: "DM Sans", Helvetica, Arial, sans-serif; color: #182127; font-size: 11px; line-height: 1.5; }
	.gkd-head { width: 100%; border-bottom: 2px solid #BF873C; margin-bottom: 18px; }
	.gkd-head td { vertical-align: middle; padding: 0 0 8px; }
	.gkd-head td.logo { width: 76px; }
	.gkd-head img { height: 64px; }
	.gkd-brand { font-family: "Zilla Slab", Georgia, serif; font-size: 20px; font-weight: bold; letter-spacing: 3px; }
	.gkd-tag { font-size: 9px; letter-spacing: 2px; color: #655649; }
	.gkd-title { font-family: "Zilla Slab", Georgia, serif; font-size: 18px; font-weight: bold; margin: 0 0 12px; }
	.gkd-meta { width: 100%; margin-bottom: 16px; }
	.gkd-meta td { width: 50%; padding: 4px 0; vertical-align: top; }
	.gkd-meta span { display: block; font-size: 9px; text-transform: uppercase; letter-spacing: 1px; color: #655649; }
	.gkd-terms { color: #182127; }
	.gkd-terms h4 { font-family: "Zilla Slab", Georgia, serif; font-size: 14px; font-weight: bold; }
	ol.gkd-terms { margin-top: 16px; padding-left: 16px; }
	ol.gkd-terms li { margin-bottom: 4px; }
	.gkd-annex { font-family: "Zilla Slab", Georgia, serif; font-size: 14px; font-weight: bold; margin-top: 22px; page-break-before: always; }
	.gkd-boq { width: 100%; border-collapse: collapse; }
	.gkd-boq th { border-bottom: 2px solid #BF873C; font-size: 9px; text-transform: uppercase; letter-spacing: 1px; color: #655649; text-align: left; padding: 4px; }
	.gkd-boq td { border-bottom: 1px solid #D6D5D2; padding: 4px; white-space: nowrap; }
	.gkd-boq td.wrap { white-space: normal; }
	.gkd-boq tr.room td { background: #F3F0E7; font-size: 10px; font-weight: bold; text-transform: uppercase; letter-spacing: 1px; padding-top: 8px; }
	.gkd-boq tr.subtotal td { border-bottom: 1px solid #BF873C; color: #655649; }
	.gkd-boq tfoot td { border-bottom: none; font-weight: bold; font-size: 12px; padding-top: 10px; }
	.gkd-boq .num { text-align: right; }
	.gkd-boq tbody { page-break-inside: avoid; }
	.gkd-note { margin-top: 14px; color: #655649; }
	.gkd-sign { width: 100%; margin-top: 40px; }
	.gkd-sign td { padding-right: 20px; vertical-align: bottom; color: #655649; }
	.gkd-sign .line { border-bottom: 1px solid #182127; height: 40px; margin-bottom: 4px; }
</style>
